data.content:
Here are the MSTest comparison assertions you need and a complete test class:

**Key assertions for boundary checking:**

| Assertion | Purpose |
|---|---|
| `Assert.IsGreaterThan(lower, actual)` | Value exceeds a bound |
| `Assert.IsLessThan(upper, actual)` | Value is below a bound |
| `Assert.IsInRange(actual, low, high)` | Value falls within a range |
| `Assert.ThrowsExactly<T>(…)` | Invalid input throws |

Here's a complete test class:

```csharp
using Contoso.Scoring;

[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    // ── CalculatePercentage ──

    [TestMethod]
    [DataRow(7, 10, 70.0)]
    [DataRow(10, 10, 100.0)]
    [DataRow(0, 10, 0.0)]
    [DataRow(1, 3, 33.333333333333336)]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(int correct, int total, double expected)
    {
        var result = _calculator.CalculatePercentage(correct, total);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void CalculatePercentage_Result_IsInValidRange()
    {
        var result = _calculator.CalculatePercentage(7, 10);

        Assert.IsGreaterThan(0.0, result);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(5, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }

    // ── GetGrade ──

    [TestMethod]
    [DataRow(90.0, "A")]
    [DataRow(100.0, "A")]
    [DataRow(89.9, "B")]
    [DataRow(80.0, "B")]
    [DataRow(79.9, "C")]
    [DataRow(70.0, "C")]
    [DataRow(69.9, "D")]
    [DataRow(60.0, "D")]
    [DataRow(59.9, "F")]
    [DataRow(0.0, "F")]
    public void GetGrade_AtBoundary_ReturnsExpectedGrade(double percentage, string expected)
    {
        var grade = _calculator.GetGrade(percentage);
        Assert.AreEqual(expected, grade);
    }

    // ── NormalizeScore ──

    [TestMethod]
    public void NormalizeScore_MidRange_ReturnsValueInRange()
    {
        var result = _calculator.NormalizeScore(45, 90);

        Assert.IsGreaterThan(0.0, result);
        Assert.IsLessThan(100.0, result);
        Assert.AreEqual(50.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_ClampedTo100()
    {
        var result = _calculator.NormalizeScore(120, 100);

        Assert.AreEqual(100.0, result);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void NormalizeScore_Zero_ReturnsZero()
    {
        Assert.AreEqual(0.0, _calculator.NormalizeScore(0, 100));
    }

    [TestMethod]
    public void NormalizeScore_NegativeRaw_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(-1, 100));
    }

    [TestMethod]
    public void NormalizeScore_ZeroMax_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(50, 0));
    }
}
```

**Summary of the comparison assertions used:**

- **`Assert.IsGreaterThan(0.0, result)`** — verifies the score is positive
- **`Assert.IsLessThan(100.0, result)`** — verifies it's below the cap
- **`Assert.IsInRange(result, 0.0, 100.0)`** — verifies both bounds at once
- **`Assert.ThrowsExactly<ArgumentOutOfRangeException>(…)`** — verifies invalid inputs are rejected

These require **MSTest 3.x+**. Use the `MSTest` NuGet package (≥ 3.8) or `MSTest.Sdk`.
